BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
DO $test$
DECLARE bank uuid;debt uuid;pid uuid;tx uuid;rev uuid;req uuid:=gen_random_uuid();p jsonb;r jsonb;err text;base text;before_cash numeric;n numeric;
BEGIN
 SELECT base_currency INTO base FROM profiles WHERE id=auth.uid();
 bank:=(open_financial_account(jsonb_build_object('request_id',gen_random_uuid(),'scope','PERSONAL','organization_id',null,'entity_id',null,'type','BANK','name','QA personal debt rollback bank','currency',base,'opening_balance',1000,'opening_date','2026-10-01','hawl_start_date','2026-01-01','fx_rate',1))->>'id')::uuid;
 p:=jsonb_build_object('action','CREATE','request_id',req,'party','QA personal creditor','description','Existing personal obligation','amount',150,'date','2026-10-14','due_date','2026-11-01','reference','QA-PERSONAL');
 r:=personal_payable_command(p);debt:=(r->>'id')::uuid;
 IF(personal_payable_command(p)->>'id')::uuid<>debt THEN RAISE EXCEPTION 'CREATE_REPLAY_FAILED';END IF;
 IF(SELECT sum(remaining_value_base) FROM lots WHERE asset_account_id=bank)<>1000 THEN RAISE EXCEPTION 'DEBT_CREATION_MOVED_CASH';END IF;
 PERFORM set_config('request.jwt.claim.sub','8ec4c7f9-83b4-4307-9d5e-de7590fa121b',true);
 IF EXISTS(SELECT 1 FROM personal_payables WHERE id=debt) THEN RAISE EXCEPTION 'PERSONAL_DEBT_RLS_FAILED';END IF;
 BEGIN PERFORM personal_payable_command(jsonb_build_object('action','PAY','request_id',gen_random_uuid(),'payable_id',debt,'account_id',bank,'amount',10,'date','2026-10-14','notes','Cross-user payment'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_ACCESS_DENIED' THEN RAISE EXCEPTION 'PERSONAL_ACCESS_GUARD:%',err;END IF;
 PERFORM set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
 p:=jsonb_build_object('action','PAY','request_id',gen_random_uuid(),'payable_id',debt,'account_id',bank,'amount',60,'date','2026-10-14','notes','Partial personal payment');
 r:=personal_payable_command(p);pid:=(r->>'id')::uuid;tx:=(r->>'transaction_id')::uuid;
 IF(personal_payable_command(p)->>'id')::uuid<>pid THEN RAISE EXCEPTION 'PAYMENT_REPLAY_FAILED';END IF;
 IF(SELECT sum(remaining_value_base) FROM lots WHERE asset_account_id=bank)<>940 THEN RAISE EXCEPTION 'PARTIAL_CASH_NOT_940';END IF;
 IF(SELECT count(*) FROM transactions WHERE id=tx AND organization_id IS NULL AND transaction_type='WITHDRAWAL')<>1 THEN RAISE EXCEPTION 'PERSONAL_CASH_SCOPE_FAILED';END IF;
 BEGIN PERFORM personal_payable_command(jsonb_set(p,'{amount}','61'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_REQUEST_CONFLICT' THEN RAISE EXCEPTION 'PAYMENT_CHANGED_REPLAY:%',err;END IF;
 p:=jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid()));p:=jsonb_set(p,'{amount}','100');
 BEGIN PERFORM personal_payable_command(p);err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_OVERPAYMENT' THEN RAISE EXCEPTION 'PERSONAL_OVERPAYMENT_GUARD:%',err;END IF;
 p:=jsonb_set(p,'{amount}','90');PERFORM personal_payable_command(p);
 IF(SELECT sum(remaining_value_base) FROM lots WHERE asset_account_id=bank)<>850 THEN RAISE EXCEPTION 'FULL_CASH_NOT_850';END IF;
 IF(SELECT sum(amount) FROM personal_payable_payments WHERE payable_id=debt)<>150 THEN RAISE EXCEPTION 'PERSONAL_FULL_PAYMENT_FAILED';END IF;
 p:=jsonb_build_object('action','REVERSE_PAYMENT','payable_id',debt,'payment_id',pid,'reason','QA wrong payment reversal');r:=personal_payable_command(p);rev:=(r->>'reversal_transaction_id')::uuid;PERFORM personal_payable_command(p);
 IF(SELECT sum(remaining_value_base) FROM lots WHERE asset_account_id=bank)<>910 THEN RAISE EXCEPTION 'PERSONAL_REVERSAL_CASH_NOT_910';END IF;
 IF(SELECT count(*) FROM transactions WHERE reversal_of_transaction_id=tx)<>1 THEN RAISE EXCEPTION 'PERSONAL_REVERSAL_DUPLICATED';END IF;
 IF(SELECT sum(p.amount) FROM personal_payable_payments p WHERE p.payable_id=debt AND NOT EXISTS(SELECT 1 FROM transactions t WHERE t.reversal_of_transaction_id=p.transaction_id))<>90 THEN RAISE EXCEPTION 'PERSONAL_REVERSAL_DEBT_NOT_60';END IF;
 IF EXISTS(SELECT 1 FROM lots WHERE asset_account_id=bank AND origin_hawl_start_date<>'2026-01-01') THEN RAISE EXCEPTION 'CASH_HAWL_CHANGED';END IF;
 PERFORM set_config('qa.personal_payable.result',jsonb_build_object('principal',150,'paid_after_reversal',90,'outstanding',60,'bank_after_reversal',910,'cash_once',true,'rls',true,'rollback',true)::text,true);
END $test$;
SELECT current_setting('qa.personal_payable.result')::jsonb result;
ROLLBACK;
